from typing import List

def calculate_minimum_cost(n: int, s: str, c: List[int]) -> int:
    min_cost = float('inf')

    for i in range(n - 1):
        if s[i] != s[i + 1]:
            cost_to_flip = min(c[i], c[i + 1])
            total_cost = cost_to_flip
            for j in range(n - 1):
                if j != i and j != i + 1 and s[j] == s[j + 1]:
                    total_cost += min(c[j], c[j + 1])
            min_cost = min(min_cost, total_cost)

    return min_cost
